// GameManager.cs - Core Game Loop
using UnityEngine;
using System.Collections;

public class GameManager : MonoBehaviour
{
    [SerializeField] private DifficultySystem _difficulty;
    [SerializeField] private ProgressTracker _progress;

    public void StartLevel(int levelId)
    {
        var adaptedDifficulty = _difficulty.GetAdaptedDifficulty(levelId);
        _progress.RecordLevelStart(levelId, adaptedDifficulty);

        // Load level with adapted difficulty
        SceneManager.LoadSceneAsync($"Level_{levelId}");
    }

    public void OnAnswerSubmitted(bool correct)
    {
        _difficulty.RecordAnswer(correct);
        _progress.UpdateProgress(correct);
    }
}

// ParentDashboard.tsx - Progress Monitoring
import { useState, useEffect } from 'react';
import { ProgressChart, AchievementBadges } from './components';

interface ChildProgress {
  skillLevel: number;
  timeSpent: number;
  achievements: string[];
  recentActivity: Activity[];
}

export const ParentDashboard = ({ childId }: { childId: string }) => {
  const [progress, setProgress] = useState<ChildProgress | null>(null);

  useEffect(() => {
    fetch(`/api/progress/${childId}`)
      .then(res => res.json())
      .then(setProgress);
  }, [childId]);

  return (
    <div className="dashboard">
      <ProgressChart data={progress?.recentActivity} />
      <AchievementBadges badges={progress?.achievements} />
    </div>
  );
};

