// DifficultySystem.cs - Adaptive Learning
using System.Collections.Generic;

public class DifficultySystem
{
    private Queue<bool> _recentAnswers = new Queue<bool>(10);
    private float _successRate => CalculateSuccessRate();

    public float GetAdaptedDifficulty(int baseDifficulty)
    {
        // Target 70-80% success rate for optimal engagement
        if (_successRate > 0.85f)
            return baseDifficulty * 1.2f; // Increase difficulty
        else if (_successRate < 0.6f)
            return baseDifficulty * 0.8f; // Decrease difficulty

        return baseDifficulty;
    }

    public void RecordAnswer(bool correct)
    {
        if (_recentAnswers.Count >= 10)
            _recentAnswers.Dequeue();
        _recentAnswers.Enqueue(correct);
    }
}

