// analytics.ts - Progress Tracking API
import { MongoClient } from 'mongodb';
import express from 'express';

const app = express();

app.get('/api/progress/:childId', async (req, res) => {
  const { childId } = req.params;

  const progress = await db.collection('progress').findOne({ childId });
  const achievements = await db.collection('achievements')
    .find({ childId, unlocked: true }).toArray();

  res.json({
    skillLevel: progress.currentLevel,
    timeSpent: progress.totalMinutes,
    achievements: achievements.map(a => a.badgeId),
    recentActivity: progress.sessions.slice(-7)
  });
});

app.post('/api/telemetry', async (req, res) => {
  const { childId, event, data } = req.body;
  await db.collection('events').insertOne({ childId, event, data, timestamp: new Date() });
  res.json({ success: true });
});
